    # 1) Open the Inventory tab. Use the exact link text as shown in the accessibility tree.
    await page.get_by_role(
        "link",
        name=(
            "The information in this tab has been changed. This tab contains invalid data. "
            "Please solve the problem before saving. Inventory"
        ),
    ).click()

    # 2) Wait for the Stock Availability control to appear and set it to Out of Stock.
    stock_availability = page.get_by_role("combobox", name="Stock Availability")
    await stock_availability.wait_for()
    # Use select_option with the option name as shown in the UI.
    await stock_availability.select_option("Out of Stock")

    # 3) Save the product. This is the final action (may navigate/reload the page).
